input.new_string:
test('discount calculation precision with banker rounding', () => {
  const line = { qty: 3, unitPrice: 100, discountPercent: 33.33 };
  const discount = lineDiscount(line);
  assert.equal(typeof discount, 'number');
  assert.equal(discount >= 0, true);
});

test('bulk discount applies for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  assert.equal(discount > 0, true);
});

test('bulk discount does not apply for qty < 10', () => {
  const line = { qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('bulk discount is 2.5% of amount after line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const lineTotal = 10000;
  const lineDisc = 0;
  const afterLineDisc = lineTotal - lineDisc;
  const bulkDisc = Math.round((afterLineDisc * 2.5) / 100);
  const expectedDiscount = bulkDisc;
  assert.equal(lineDiscount(line), expectedDiscount);
});

test('bulk discount applies after line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const lineTotal = 10000;
  const lineDisc = Math.round((lineTotal * 10) / 100);
  const afterLineDisc = lineTotal - lineDisc;
  const bulkDisc = Math.round((afterLineDisc * 2.5) / 100);
  const expectedDiscount = lineDisc + bulkDisc;
  assert.equal(lineDiscount(line), expectedDiscount);
});

test('bulk discount with exactly 10 units', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  const expectedBulkDisc = Math.round((1000 * 2.5) / 100);
  assert.equal(discount, expectedBulkDisc);
});

test('bulk discount with large quantity', () => {
  const line = { qty: 1000, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  const expectedBulkDisc = Math.round((100000 * 2.5) / 100);
  assert.equal(discount, expectedBulkDisc);
});

test('bulk discount with both line discount and bulk discount', () => {
  const line = { qty: 100, unitPrice: 100, discountPercent: 20, vatRate: 21 };
  const lineTotal = 10000;
  const lineDisc = Math.round((lineTotal * 20) / 100);
  const afterLineDisc = lineTotal - lineDisc;
  const bulkDisc = Math.round((afterLineDisc * 2.5) / 100);
  const totalDisc = lineDisc + bulkDisc;
  assert.equal(lineDiscount(line), totalDisc);
});

test('bulk discount is counted in invoiceTotals discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.discount > 0, true);
});

test('VAT is calculated on amount after both discounts', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);
  const lineTotal = 10000;
  const lineDisc = 0;
  const afterLineDisc = lineTotal - lineDisc;
  const bulkDisc = Math.round((afterLineDisc * 2.5) / 100);
  const baseForVat = lineTotal - lineDisc - bulkDisc;
  const expectedVat = Math.round((baseForVat * 21) / 100);
  assert.equal(result.vat, expectedVat);
});

test('bulk discount with mixed line discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  const line1Disc = Math.round((5000 * 10) / 100);
  const line2Disc = Math.round((10000 * 10) / 100);
  const line2After = 10000 - line2Disc;
  const line2BulkDisc = Math.round((line2After * 2.5) / 100);
  const totalDisc = line1Disc + line2Disc + line2BulkDisc;
  assert.equal(result.discount, totalDisc);
});

test('bulk discount at threshold (qty = 10)', () => {
  const line9 = { qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const line10 = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const disc9 = lineDiscount(line9);
  const disc10 = lineDiscount(line10);
  assert.equal(disc9, 0);
  assert.equal(disc10 > 0, true);
});

test('bulk discount does not exceed line total', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 99, vatRate: 21 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  assert.equal(discount <= total, true);
});

test('invoiceTotals with only bulk discount items', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 20, unitPrice: 500, discountPercent: 0, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.discount > 0, true);
  assert.equal(result.total > 0, true);
});

test('bulk discount with zero line discount percent', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  const expectedBulkDisc = Math.round((10000 * 2.5) / 100);
  assert.equal(discount, expectedBulkDisc);
});

test('invoiceTotals bulk discount reduces total', () => {
  const invoiceNoBulk = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const invoiceWithBulk = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const resultNoBulk = invoiceTotals(invoiceNoBulk);
  const resultWithBulk = invoiceTotals(invoiceWithBulk);
  assert.equal(resultWithBulk.total < resultNoBulk.total, true);
});

